window.HOEREN_TESTS[64] = {"id":"im-elektronikgeschaeft","name":"Im Elektronikgeschäft","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Heute ist großer Aktionstag im Elektronikmarkt. Alle Fernseher sind 20 Prozent günstiger, alle Laptops sogar 30 Prozent. Handys sind leider nicht im Angebot, die bleiben zum normalen Preis. Die Aktion gilt nur heute bis 20 Uhr. Kommen Sie schnell, der Vorrat ist begrenzt. Wir freuen uns auf Sie!","gender":"f","q":"Was ist nicht im Angebot?","opts":["Die Fernseher.","Die Handys.","Die Laptops."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Du, mein Handy ist kaputt — das Display ist gesprungen. Der Akku ist nicht leer, und verloren ist es auch nicht. Ich brauche ein neues, aber kein teures. Du kennst dich aus mit Technik. Kannst du mir ein gutes günstiges Modell empfehlen? Vielleicht gehen wir zusammen ins Geschäft? Ruf zurück, danke!","gender":"m","q":"Was ist mit Markus' Handy?","opts":["Das Display ist gesprungen.","Der Akku ist leer.","Es ist verloren."],"correct":0},{"transcript":"Achtung Kunden: Die Lieferung der neuen Spielekonsolen verspätet sich. Sie kommen nicht diese Woche und auch nicht morgen, sondern erst in zwei Wochen. Wer schon vorbestellt hat, wird automatisch benachrichtigt. Eine Anzahlung ist nicht nötig. Wir bitten um Geduld und entschuldigen uns für die Wartezeit!","gender":"m","q":"Wann kommen die Konsolen?","opts":["In zwei Wochen.","Diese Woche.","Morgen."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Ich habe einen neuen Drucker gekauft, aber er funktioniert nicht. Das Handy und der Fernseher sind in Ordnung. Ich glaube, ich mache etwas falsch beim Anschließen. Du bist doch gut mit Computern. Kannst du heute Abend vorbeikommen und mir helfen? Ich lade dich zum Essen ein. Bis später!","gender":"f","q":"Womit braucht Anna Hilfe?","opts":["Mit dem Fernseher.","Mit dem Handy.","Mit dem Drucker."],"correct":2},{"transcript":"Liebe Kunden: Auf alle Geräte geben wir zwei Jahre Garantie, nicht nur ein Jahr. Gegen einen kleinen Aufpreis können Sie die Garantie auf drei Jahre verlängern. Bei Reparaturen innerhalb der Garantie zahlen Sie nichts. Bewahren Sie unbedingt Ihren Kassenbon auf. Fragen Sie unsere Mitarbeiter an der Information!","gender":"f","q":"Wie lange ist die normale Garantie?","opts":["Ein Jahr.","Zwei Jahre.","Drei Jahre."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Laden hat bis acht auf und die Angebote hängen an der Wand."},{"speaker":"Lisa","gender":"f","text":"Endlich schaffen wir es hin. Ich brauche etwas für die Arbeit und für die Bahn."},{"speaker":"Lukas","gender":"m","text":"Ich kaufe einen Laptop. Der alte wird in der Schule einfach zu langsam."},{"speaker":"Lisa","gender":"f","text":"Ich nehme Kopfhörer für die Bahn. Damit bleibt es um mich herum leise."},{"speaker":"Lukas","gender":"m","text":"Braucht jemand von uns ein neues Handy?"},{"speaker":"Lisa","gender":"f","text":"Nein. Ein Handy kauft heute niemand aus der Runde."},{"speaker":"Lukas","gender":"m","text":"Tom schaut abends Filme zusammen mit der ganzen Familie."},{"speaker":"Lisa","gender":"f","text":"Tom holt einen großen Fernseher für die Familie. Der Bildschirm im Wohnzimmer soll hell genug sein."},{"speaker":"Lukas","gender":"m","text":"Sara fährt nächste Woche in die Berge und will Erinnerungen mitbringen."},{"speaker":"Lisa","gender":"f","text":"Sara sucht eine Kamera für die Bergtour. Sie will die Wege und den See festhalten."},{"speaker":"Lukas","gender":"m","text":"Braucht jemand einen Drucker für das Arbeitszimmer?"},{"speaker":"Lisa","gender":"f","text":"Nein. Einen Drucker brauchen wir nicht. Wir machen das im Büro."},{"speaker":"Lukas","gender":"m","text":"Tim spielt am Wochenende lange mit seinen Freunden im Wohnzimmer."},{"speaker":"Lisa","gender":"f","text":"Tim nimmt sich eine Spielekonsole. Die Kartons mit den Spielen liegen schon zu Hause."},{"speaker":"Lukas","gender":"m","text":"Dann gehen wir mit den fünf Sachen zusammen zur Kasse."},{"speaker":"Lisa","gender":"f","text":"Ich habe die Karte schon in der Hand."}],"options":[{"letter":"a","text":"Spielekonsole"},{"letter":"b","text":"Handy"},{"letter":"c","text":"Lautsprecher"},{"letter":"d","text":"Kamera"},{"letter":"e","text":"Fernseher"},{"letter":"f","text":"Drucker"},{"letter":"g","text":"Laptop"},{"letter":"h","text":"Tablet"},{"letter":"i","text":"Kopfhörer"}],"items":[{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"i"},{"person":"Tom","correct":"e"},{"person":"Sara","correct":"d"},{"person":"Tim","correct":"a"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, ich interessiere mich für diesen Laptop. Was kostet er?"},{"speaker":"Verkäufer","gender":"m","text":"Normal kostet er 699 Euro, heute im Angebot 599 Euro."},{"speaker":"Kunde","gender":"m","text":"Ist eine Tasche dabei?"},{"speaker":"Verkäufer","gender":"m","text":"Nein, die Tasche kostet 20 Euro extra. Mit Tasche sind das dann 619 Euro."},{"speaker":"Kunde","gender":"m","text":"Dann nehme ich nur den Laptop für 599 Euro, ohne Tasche. Danke."}],"q":"Was kostet der Laptop heute?","opts":["599 Euro.","699 Euro.","619 Euro."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich möchte dieses Handy umtauschen, bitte."},{"speaker":"Verkäuferin","gender":"f","text":"Was ist das Problem? Ist es kaputt oder zu teuer?"},{"speaker":"Kundin","gender":"f","text":"Nein, kaputt ist es nicht, und zu teuer war es auch nicht. Es ist mir nur zu groß, es passt nicht in die Tasche."},{"speaker":"Verkäuferin","gender":"f","text":"Kein Problem, haben Sie den Bon dabei?"},{"speaker":"Kundin","gender":"f","text":"Ja, hier ist der Bon. Haben Sie ein kleineres Modell?"},{"speaker":"Verkäuferin","gender":"f","text":"Ja, wir haben ein kleineres. Kommen Sie bitte mit."}],"q":"Warum möchte sie das Handy umtauschen?","opts":["Es ist kaputt.","Es ist zu teuer.","Es ist zu groß."],"correct":2},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, können Sie meinen Computer reparieren?"},{"speaker":"Techniker","gender":"m","text":"Was ist denn los? Ist der Bildschirm schwarz, oder ist er zu laut?"},{"speaker":"Mann","gender":"m","text":"Nein, der Bildschirm ist nicht schwarz, und zu laut ist er auch nicht. Er startet nur sehr langsam."},{"speaker":"Techniker","gender":"m","text":"Wahrscheinlich ein Virus. Ich schaue mal, das dauert etwa eine Stunde."},{"speaker":"Mann","gender":"m","text":"Gut, dann lasse ich ihn hier. Danke schön."}],"q":"Was ist das Problem mit dem Computer?","opts":["Er ist zu laut.","Er startet langsam.","Der Bildschirm ist schwarz."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, liefern Sie den Fernseher nach Hause?"},{"speaker":"Verkäufer","gender":"m","text":"Ja, gegen 30 Euro Gebühr. Die Lieferung ist also nicht kostenlos."},{"speaker":"Frau","gender":"f","text":"Und der Aufbau? Ist beides frei?"},{"speaker":"Verkäufer","gender":"m","text":"Nein, beides ist nicht frei. Den Aufbau machen wir kostenlos dazu, nur die Lieferung kostet."},{"speaker":"Frau","gender":"f","text":"Gut, dann nehme ich Lieferung und Aufbau. Danke."}],"q":"Was ist kostenlos?","opts":["Der Aufbau.","Die Lieferung.","Beides."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, wie lange hält der Akku bei diesem Modell?"},{"speaker":"Verkäuferin","gender":"f","text":"Bei diesem Modell zwei Tage. Das ganz günstige Modell hält nur einen Tag."},{"speaker":"Kunde","gender":"m","text":"Und beim teureren Modell?"},{"speaker":"Verkäuferin","gender":"f","text":"Drei Tage, aber das kostet 100 Euro mehr als das andere."},{"speaker":"Kunde","gender":"m","text":"Dann nehme ich das teurere, drei Tage sind mir wichtig. Danke."}],"q":"Wie lange hält der Akku beim teureren Modell?","opts":["Zwei Tage.","Drei Tage.","Einen Tag."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Krause, einem Verkäufer im Elektronikmarkt. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Krause, was wünschen sich die Kunden heute im Elektronikmarkt?"},{"speaker":"Krause","gender":"m","text":"Die meisten wollen einfache Geräte, die sofort funktionieren. Nicht kompliziert. Viele haben keine Zeit für lange Anleitungen. Ein Gerät soll angehen und laufen, das ist ihnen wichtig."},{"speaker":"Reporterin","gender":"f","text":"Kaufen die Leute lieber teuer oder günstig?"},{"speaker":"Krause","gender":"m","text":"Das ist gemischt. Beim Handy geben viele viel Geld aus, bei Kabeln und kleinen Sachen wollen sie sparen. Also sparen sie nicht beim Handy, sondern bei den kleinen Dingen."},{"speaker":"Reporterin","gender":"f","text":"Was ist der häufigste Fehler der Kunden?"},{"speaker":"Krause","gender":"m","text":"Die Leute kaufen zu viel. Sie nehmen Geräte mit vielen Funktionen, die sie nie nutzen. Am Ende steht das Gerät zu Hause und niemand benutzt die Extra-Sachen."},{"speaker":"Reporterin","gender":"f","text":"Wie ist es mit dem Online-Handel?"},{"speaker":"Krause","gender":"m","text":"Online ist oft billiger, das stimmt. Aber bei uns kann man die Geräte anfassen und Fragen stellen. Viele Kunden kommen extra, weil sie das Gerät sehen und hören wollen, bevor sie kaufen."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie den Kunden?"},{"speaker":"Krause","gender":"m","text":"Überlegen Sie, was Sie wirklich brauchen. Kaufen Sie nicht zu viel. Und werfen Sie alte Geräte nicht weg — bringen Sie sie zum Recycling oder geben Sie sie weiter. Das ist besser für die Umwelt."}],"items":[{"q":"Die meisten Kunden wollen heute einfache Geräte.","correct":"ja"},{"q":"Beim Handy sparen die Leute am meisten.","correct":"nein"},{"q":"Herr Krause sagt, viele Leute kaufen zu viel.","correct":"ja"},{"q":"Im Geschäft kann man die Geräte anfassen.","correct":"ja"},{"q":"Er rät, alte Geräte einfach wegzuwerfen.","correct":"nein"}]}]};
